import{_ as t,o as s,c as a,a2 as r}from"./chunks/framework.C3idr2hZ.js";const n="/orc/assets/git-review.DrCSLLwi.png",i="/orc/assets/pr-review.i43aKfek.png",o="/orc/assets/shared-form-controls.B9bcxKqO.png",l="/orc/assets/pr-comment-editor.D-iK_EqH.png",c="/orc/assets/pr-ci.C2heRk0Q.png",h="/orc/assets/palette.CLyUobKf.png",d="/orc/assets/host-selector.BIXkUnQJ.png",v=JSON.parse('{"title":"Terminal workspace","description":"","frontmatter":{},"headers":[],"relativePath":"docs/terminal-workspace.md","filePath":"docs/terminal-workspace.md","lastUpdated":1794601173000}'),p={name:"docs/terminal-workspace.md"};function m(u,e,g,f,w,b){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="terminal-workspace" tabindex="-1">Terminal workspace <a class="header-anchor" href="#terminal-workspace" aria-label="Permalink to &quot;Terminal workspace&quot;">​</a></h1><p>Use Terminals to keep shells and coding agents beside Files and Git views. Splitting or expanding a pane preserves running terminal processes.</p><h2 id="find-and-manage-terminals" tabindex="-1">Find and manage terminals <a class="header-anchor" href="#find-and-manage-terminals" aria-label="Permalink to &quot;Find and manage terminals&quot;">​</a></h2><ul><li>Press <strong>Ctrl+K</strong> (<strong>Cmd+K</strong> on macOS) and choose <strong>Terminals</strong>, or use the terminal picker icon beside the split controls.</li><li>Search friendly names, full folder paths, agent types or host aliases. An empty terminal search shows recent terminals for this browser session.</li><li>Select a result to open the existing terminal. A terminal already visible in another pane is focused there, rather than mounted twice.</li><li>Use a session&#39;s three-dot menu or right-click its name to <strong>Rename</strong>, <strong>Duplicate</strong> or <strong>Close</strong>. Duplicate starts a fresh session of the same type on the same host and in the same folder; it does not copy an agent conversation or create a worktree.</li><li><strong>Expand pane</strong> temporarily fills the terminal workspace with one pane. <strong>Restore split layout</strong> restores the other panes. This does not enter browser fullscreen or stop their processes.</li></ul><p>Names survive browser reloads for the lifetime of the running API&#39;s in-memory terminal. Closing a pane preserves its terminal; closing the terminal stops it.</p><h2 id="files-and-git" tabindex="-1">Files and Git <a class="header-anchor" href="#files-and-git" aria-label="Permalink to &quot;Files and Git&quot;">​</a></h2><p>Files has open-file tabs, dirty markers and Git change badges. Switching between Files and Git or arranging panes preserves in-page file tabs and editor drafts. Drafts are not durable storage; save before closing the page. Saves detect conflicting disk changes and retain the draft for explicit resolution.</p><p>Browser Back and Forward restore Files or Git, including shared links opened on another device. Restored views stay in place when you focus another pane or reload.</p><p>Git opens with <strong>Local changes</strong>: a grouped file list, path and change-state filters, selected staging, unified or side-by-side diffs, and links into Files. The commit message stays full width at the bottom. Click the branch name to expand branch/worktree controls; use the task-link icon beside the file-sidebar toggle to link an ORC task. <strong>New worktree</strong> sits beside the worktree selector. The file list collapses into a picker in narrow panes. Opening a worktree preserves the selected terminal host.</p><p>When space permits, the pane toolbar shows branch/changed-file count, a linked ORC task and the current branch&#39;s open PR. CI appears beside the PR when GitHub provides its current head-commit checks and statuses. Inaccessible or incomplete CI is hidden; no reported checks is shown separately from passing checks. CI refreshes while the workspace is open. The wider task and PR details disappear in narrow panes.</p><p>GitHub access uses <code>gh</code> credentials on the terminal&#39;s host, with the server&#39;s configured GitHub token as a fallback. A checkout without a GitHub <code>origin</code> remote is reported separately from unavailable authentication.</p><h2 id="review-a-pull-request" tabindex="-1">Review a pull request <a class="header-anchor" href="#review-a-pull-request" aria-label="Permalink to &quot;Review a pull request&quot;">​</a></h2><p>When GitHub access and a current-branch PR are available, choose <strong>PR #</strong> in Git or click the pane toolbar PR link. The separate external-link icon opens GitHub in your browser. PR review shows committed PR changes separately from dirty local files.</p><p><strong>Files changed</strong> provides file filtering, unified/split patches and review threads. Scroll continuously through the loaded files, or use the file list/picker to jump to a file. Click a diff line number to open an editor directly beneath that line, or <strong>Reply</strong> below a thread. Editors stay closed until an explicit action; use the close icon or Escape to dismiss and retain the draft. <strong>Discussion</strong> shows the description, general comments, review summaries and inline threads; choose <strong>Add comment</strong> for a general PR comment. Sending requires an explicit <strong>Send comment</strong> action and uses the authenticated GitHub account. This view does not approve reviews, request changes or merge PRs.</p><p>Drafts are kept separately by file, line and side. While a comment is sending, editing and additional sends are disabled until its result arrives. Drafts remain in the current page when switching review views or after a failed send; they do not survive reloading the page. A changed PR head requires refreshing and explicitly selecting a line again before sending an inline draft; if the old line disappears, the draft remains available until you select a current line. After an uncertain network result, check GitHub before retrying. Closed PRs are read-only. Large/partial or binary changes link back to GitHub for complete inspection. Descriptions and comments display as plain text without loading embedded remote images.</p><h2 id="dev-server-and-preview" tabindex="-1">Dev server and preview <a class="header-anchor" href="#dev-server-and-preview" aria-label="Permalink to &quot;Dev server and preview&quot;">​</a></h2><p>A project can save a <strong>Dev script</strong> with its <a href="./configuration#project-workspace-environment">workspace environment</a>. Open a project terminal&#39;s three-dot menu and choose <strong>Start dev server</strong>. The script runs in a new shell in the same folder and host; the first <code>http(s)</code> URL it prints becomes the preview link. <strong>Preview</strong> appears in the pane toolbar and in the terminal&#39;s menu. The link is cleared when that dev terminal exits.</p><p>Terminals that belong to a project receive its port block and environment variables. A session&#39;s inspector shows the workspace ports, setup state and preview; a task&#39;s Git links show the same workspace status with its setup output when the setup script failed. Setup runs once per managed worktree, before the first agent starts there; a failure is reported but does not block the agent.</p><h2 id="local-and-ssh-hosts" tabindex="-1">Local and SSH hosts <a class="header-anchor" href="#local-and-ssh-hosts" aria-label="Permalink to &quot;Local and SSH hosts&quot;">​</a></h2><p><strong>New terminal</strong> selects Local or an existing SSH-config host for that launch. The launcher offers a shell plus enabled named providers from <strong>Settings → Providers</strong> whose native CLI is installed on that host (or has a configured local executable). Provider launches receive their environment overrides and, for Claude/Codex, their default model. Chat JSON options apply to the chat adapter; package setups retain their own launch configuration. A plain shell does not receive a coding provider&#39;s environment. Selecting a host scopes launcher availability, folder browsing and worktrees to that host. The global SSH setting is unchanged. Searching a supported SSH host in the terminal palette offers <strong>New terminal on that host</strong>, which opens the launcher without executing anything automatically.</p><p>Remote folder choices are kept separately from Local during the launch menu&#39;s lifetime. The new-worktree checkbox preference is remembered. Existing terminals retain their host, and resumed agent sessions retain their saved execution host. Resuming a session in a terminal from the session list reattaches the running terminal when one exists; <strong>Fork in terminal</strong> always opens a new terminal on the same host and folder and leaves the source conversation and any resume terminal unchanged.</p><h3 id="supported-execution-hosts" tabindex="-1">Supported execution hosts <a class="header-anchor" href="#supported-execution-hosts" aria-label="Permalink to &quot;Supported execution hosts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API platform</th><th>Local PTYs</th><th>SSH terminals</th></tr></thead><tbody><tr><td>Windows with Bun 1.4.2+</td><td>Supported through ConPTY</td><td>One SSH connection per terminal plus a per-host callback tunnel (no OpenSSH multiplexing on Windows); trusted host keys and noninteractive key authentication</td></tr><tr><td>Linux/macOS with supported Bun PTYs</td><td>Supported</td><td>Requires OpenSSH multiplexing, trusted host keys and noninteractive key authentication</td></tr></tbody></table><p>The SSH transport needs a callback to the ORC API. Automatic reverse forwarding requires the SSH key/server to permit forwarding. A restricted key is reported as an error; the application does not change SSH permissions or trust settings. An explicitly configured callback port can use an already reachable API endpoint.</p><p>Per-terminal SSH PTYs and their Files/Git operations are host-aware. Automatic agent-history discovery still follows the globally configured execution host; this change does not add discovery across every terminal host.</p><p>Shared Input, Select and Textarea components use compact desktop controls with the same larger touch sizes on phones. Page-specific size overrides are preserved.</p><h2 id="ui-examples" tabindex="-1">UI examples <a class="header-anchor" href="#ui-examples" aria-label="Permalink to &quot;UI examples&quot;">​</a></h2><p>The Local changes and PR review screenshots below show the real source checkout and a read-only fetch of PR #94. The shared-controls screenshot shows an unsaved task form in the isolated preview. The mobile PR and light Git screenshots below use explicit review fixtures. The other examples use disposable test checkouts: host names, linked task, PR and CI there are explicit fixtures, not evidence of live remote execution.</p><p><img src="'+n+'" alt="Local changes with full-width commit field"></p><p><img src="'+i+'" alt="Actual pull request files and diff"></p><p><a href="../screenshots/terminal-workspace/pr-review-mobile.png">Mobile PR review fixture</a> · <a href="../screenshots/terminal-workspace/git-review-light.png">Light Git fixture</a></p><p><img src="'+o+'" alt="Shared form controls"></p><p><img src="'+l+'" alt="Inline comment editor with close action (review fixture)"></p><p><a href="../screenshots/terminal-workspace/pr-comment-editor-mobile.png">Mobile comment editor fixture</a></p><p><img src="'+c+'" alt="Compact PR and CI context"></p><p><img src="'+h+'" alt="Search existing terminals"></p><p><img src="'+d+'" alt="Per-terminal host selection"></p>',37)])])}const x=t(p,[["render",m]]);export{v as __pageData,x as default};
